// chacha20: the ChaCha20 stream cipher of RFC 8439 (key bytes 0-31, nonce
// 000000090000004a00000000, counter from 1) over 8 MiB of generated bytes.
// Prints a position-weighted checksum of the encrypted bytes, and the
// first 16 of them in hexadecimal.

fn qr(s: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
    s[a] = s[a].wrapping_add(s[b]);
    s[d] = (s[d] ^ s[a]).rotate_left(16);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_left(12);
    s[a] = s[a].wrapping_add(s[b]);
    s[d] = (s[d] ^ s[a]).rotate_left(8);
    s[c] = s[c].wrapping_add(s[d]);
    s[b] = (s[b] ^ s[c]).rotate_left(7);
}

fn block(key: &[u32; 8], nonce: &[u32; 3], counter: u32) -> [u8; 64] {
    let mut init = [0u32; 16];
    init[..4].copy_from_slice(&[0x61707865, 0x3320646E, 0x79622D32, 0x6B206574]);
    init[4..12].copy_from_slice(key);
    init[12] = counter;
    init[13..].copy_from_slice(nonce);
    let mut s = init;
    for _ in 0..10 {
        qr(&mut s, 0, 4, 8, 12);
        qr(&mut s, 1, 5, 9, 13);
        qr(&mut s, 2, 6, 10, 14);
        qr(&mut s, 3, 7, 11, 15);
        qr(&mut s, 0, 5, 10, 15);
        qr(&mut s, 1, 6, 11, 12);
        qr(&mut s, 2, 7, 8, 13);
        qr(&mut s, 3, 4, 9, 14);
    }
    let mut out = [0u8; 64];
    for i in 0..16 {
        out[4 * i..4 * i + 4].copy_from_slice(&s[i].wrapping_add(init[i]).to_le_bytes());
    }
    out
}

fn main() {
    let n = 1usize << 23;
    let words = |b: &[u8]| -> Vec<u32> { b.chunks(4).map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect() };
    let key: [u32; 8] = words(&(0..32u8).collect::<Vec<_>>()).try_into().unwrap();
    let nonce: [u32; 3] = words(&[0, 0, 0, 9, 0, 0, 0, 0x4a, 0, 0, 0, 0]).try_into().unwrap();
    let mut out = vec![0u8; n];
    for b in 0..n / 64 {
        let ks = block(&key, &nonce, 1 + b as u32);
        for j in 0..64 {
            let i = 64 * b + j;
            out[i] = ((i as i64 * 2654435761) >> 13 & 255) as u8 ^ ks[j];
        }
    }
    let check: i64 = out.iter().enumerate().map(|(i, &x)| x as i64 * (i as i64 % 251 + 1)).sum();
    println!("{} {}", check, out[..16].iter().map(|b| format!("{:02x}", b)).collect::<String>());
}
